package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;
/** Quick UI shortcuts linked to the canonical repair inventory. No stock is stored here. */
public final class QuickRepairButtonStore{private final CoreStore.DbProvider provider;public QuickRepairButtonStore(CoreStore.DbProvider p){provider=p;}
 public List<Item> active(){ArrayList<Item> out=new ArrayList<>();try(Cursor c=provider.db().rawQuery("SELECT b.button_id,b.label,b.icon,b.part_id,p.name,p.quantity,p.sale_price,p.currency FROM quick_repair_buttons b JOIN repair_inventory p ON p.part_id=b.part_id WHERE b.active=1 AND p.deleted_at IS NULL ORDER BY b.sort_order,b.label",null)){while(c.moveToNext())out.add(new Item(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getInt(5),c.getDouble(6),c.getString(7)));}return out;}
 public String save(String id,String label,String icon,String partId,int sort)throws Exception{String l=req(label,"اسم الزر"),pid=req(partId,"قطعة الصيانة");SQLiteDatabase db=provider.db();try(Cursor c=db.rawQuery("SELECT 1 FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{pid})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة المرتبطة غير موجودة");}long now=System.currentTimeMillis();String bid=id==null||id.trim().isEmpty()?"quick-"+java.util.UUID.randomUUID():id.trim();ContentValues v=new ContentValues();v.put("button_id",bid);v.put("label",l);v.put("icon",icon==null||icon.trim().isEmpty()?"🔧":icon.trim());v.put("part_id",pid);v.put("sort_order",sort);v.put("active",1);v.put("updated_at",now);v.put("created_at",now);db.insertWithOnConflict("quick_repair_buttons",null,v,SQLiteDatabase.CONFLICT_REPLACE);return bid;}
 public void disable(String id){ContentValues v=new ContentValues();v.put("active",0);v.put("updated_at",System.currentTimeMillis());provider.db().update("quick_repair_buttons",v,"button_id=?",new String[]{id});}
 public static final class Item{public final String id,label,icon,partId,partName,currency;public final int quantity;public final double salePrice;Item(String i,String l,String x,String p,String n,int q,double s,String c){id=i;label=l;icon=x;partId=p;partName=n;quantity=q;salePrice=s;currency=c;}}
 private static String req(String v,String n){String s=v==null?"":v.trim();if(s.isEmpty())throw new IllegalArgumentException(n+" مطلوب");return s;}}
